def add_chiiki_kangaekata(doc):
    """第5章9（地域生活支援事業）に、告示が求める「実施に関する考え方」を追加する。

    告示 第三 二 3 ㈡ は、事業の種類ごとに「実施に関する考え方及び量の見込み」を
    定めるとしている。現行計画は量の見込みは備えているが、実施に関する考え方が
    末尾の総括1文にとどまるため、事業ごとの考え方を補う。
    """
    anchor = find_para(doc, "９　地域生活支援事業の実施目標", style="Heading 2")
    tbl = find_block_after(doc, anchor, "tbl")
    insert_before(anchor, [
        make_empty(doc),
    ])
    # 第5章冒頭の注記が、差し替え前の列名（R6～R8実績・R9～R11見込量）を
    # 指したままになっているため、現在の列名に合わせる
    note = find_table_where(doc, 0, 0, "【要更新・要確認】下表の「R6～R8実績」")
    replace_note_text(
        doc, note,
        "【要更新・要確認】第５章３〜７の見込量表の「令和９年度」〜「令和11年度」の列は、"
        "村の最新データ（サービス利用実績、対象者の状況変化、新規利用希望等）に基づき"
        "確定してください。特に居宅介護・共同生活援助等、令和５年度以降に"
        "利用者数の変動があったサービスについては、直近の状況を反映する必要があります。")
    changes.append("第5章冒頭：注記が指す列名を現在の表頭（令和９〜11年度）に是正"
                   "（差し替え前の「R6～R8実績」「R9～R11見込量」を参照していた）")

    note7 = find_table_where(doc, 0, 0, "【要更新・要確認】児童発達支援について")
    replace_note_text(
        doc, note7,
        "【要更新・要確認】児童発達支援について、令和８年度時点の対象児童の"
        "就学・通園状況（幼稚園への通園希望等）を反映し、"
        "令和９〜11年度の見込量を確定してください。")
    changes.append("第5章7：注記の年度表記を令和表記に統一（「R9～R11」を用いていた）")

    # 障がい児の区分の制度と、見込量で勘案する受入体制。
    # 見出しの直後に表（注記ボックス）を挟むと apply_mikomiryo が
    # それを見込量表と取り違えるため、見込量表の後ろにある注記を起点にする。
    anchor7 = find_table_where(doc, 0, 0, "【要更新・要確認】児童発達支援について")
    insert_after(anchor7, [
        make_note(doc,
                  "【区分の制度について】障がい児通所支援の支給決定は、"
                  "５領域20項目の調査指標等により行います。"
                  "成人の障害支援区分１〜６を一律に付ける仕組みではありません。"
                  "短期入所について用いる障がい児支援区分１〜３は、"
                  "食事・排せつ・入浴・移動等の介助や行動面の支援の度合により"
                  "判定するもので、成人の障害支援区分１〜６とは別の制度です。"
                  "医療的ケア児については、医療的ケア判定スコアが"
                  "報酬及び支援体制に関係します。"
                  "本計画では障がい児の見込量を区分別には管理せず、"
                  "年齢・学年・障がいの特性・医療的ケアの有無・"
                  "現に利用しているサービス・支給決定量により管理します。"),
        make_note(doc,
                  "【見込量で勘案する事項】国の基本指針は、障がい児通所支援の"
                  "見込量について、児童人口の推移、現に利用している児童数、"
                  "ニーズ、重症心身障がい児及び医療的ケア児の状況、"
                  "放課後児童クラブ、小学校・中学校・特別支援学校等の"
                  "受入れ及び利用の状況、施設を退所した児童、"
                  "１人当たりの利用量を勘案することを求めています。"
                  "また告示 第三の二の２㈠は、指定通所支援等の見込量を"
                  "保育所等における障害児の受入れの体制の整備状況を"
                  "踏まえて設定するものとしています。"
                  "したがって、学校に在籍している障がい児の数を"
                  "そのまま放課後等デイサービスの必要者数とはしません。"
                  "村内の保育所・認定こども園・放課後児童クラブの"
                  "受入人数と加配の状況（村への照会M-11）の回答を得て、"
                  "考え方欄に反映します。"),
        make_empty(doc),
    ])
    changes.append("第5章7：障がい児通所支援の支給決定は5領域20項目によること、"
                   "障がい児支援区分1〜3は短期入所に係る別制度であることを注記。"
                   "見込量で勘案する事項（放課後児童クラブ・学校の受入状況ほか）を追加")

    # 表頭の年度表記を他の見込量表と同じ令和表記に揃える（原本は「R8見込量」等）
    hdr = ["事業の種類", "令和８年度\n見込量（前計画）",
           "令和９年度", "令和10年度", "令和11年度"]
    row0 = Table(tbl, doc).rows[0]
    if len(row0.cells) != len(hdr):
        raise LookupError(f"地域生活支援事業の表頭が{len(row0.cells)}列（5列のはず）")
    for cell, val in zip(row0.cells, hdr):
        _write_cell(cell, val, bold=True, size=9)
    changes.append("第5章9：地域生活支援事業の表頭の年度表記を令和表記に統一"
                   "（原本は「R8見込量」等の略記）")
    # 見込量表の直後（注記の前）に考え方の節を差し込む
    insert_after(tbl, [
        make_para(doc, "■　事業ごとの実施に関する考え方", style="Heading 3"),
        make_para(doc,
                  "国の基本指針は、地域生活支援事業について"
                  "「実施する事業の内容」「各年度における事業の種類ごとの実施に関する考え方"
                  "及び量の見込み」「各事業の見込量の確保のための方策」"
                  "「その他実施に必要な事項」を定めるとしています（第三の二の３）。"
                  "このうち実施に関する考え方は、次のとおり整理します。"),
        make_table(doc, [
            ["区分", "事業", "実施に関する考え方"],
            ["継続して\n実施する事業",
             "障がい者相談支援事業、成年後見制度利用支援事業、"
             "日常生活用具給付等事業、地域活動支援センター機能強化事業、"
             "日中一時支援事業、福祉ホーム事業",
             "実績のある事業として継続します。日常生活用具給付等事業のうち"
             "排泄管理支援用具は令和３年度40件から令和５年度69件へ増加しており、"
             "高齢化の進行に伴い引き続き増加が見込まれるため、実績の傾向を反映して"
             "見込量を設定します。地域活動支援センター機能強化事業及び日中一時支援事業は、"
             "実績が前計画の見込量を上回っているため、実績を基礎とします。"],
            ["実績がない\n必須事業",
             "理解促進研修・啓発事業、自発的活動支援事業、意思疎通支援事業、"
             "移動支援事業",
             "いずれも法により市町村が実施するものとされている必須事業です。"
             "実績がないことをもって需要がないと判断せず、"
             "利用が生じた場合に速やかに対応できる体制を確保します。"
             "特に意思疎通支援事業については、国の基本指針の見直し事項において"
             "意思疎通支援従事者の養成・派遣体制の整備、幅広い年齢層の支援者の養成、"
             "障がい当事者に対するＩＣＴ機器の利用支援が挙げられていることを踏まえ、"
             "県及び圏域の派遣体制へのアクセスを確保します。"],
            ["圏域で対応する事業",
             "障がい者相談支援事業、地域活動支援センター機能強化事業",
             "会津北部圏域（猪苗代町・磐梯町・湯川村・北塩原村）の"
             "地域生活支援拠点等整備事業と一体で実施し、"
             "村単独では確保が難しい機能を圏域で補完します。"],
        ], [1600, 3000, 5038]),
        make_note(doc,
                  "【要更新・要確認】①移動支援事業は令和３年度から令和８年度まで"
                  "見込量・実績とも一貫して０人です。本村は北山・大塩・檜原の各地区が分散し、"
                  "冬季の移動が困難であるという地域特性があり、実績０が続くことと整合しません。"
                  "制度が知られていないのか、同行援護・村単独事業・家族送迎で代替されているのか、"
                  "需要そのものがないのかを確認してください。"
                  "②福祉ホーム事業は令和３〜５年度に１〜２人の実績がありますが、"
                  "令和６〜８年度の見込量は０人としています。"
                  "実績のある事業に見込量を置かないと補助金の算定と計画の整合が取れないため、"
                  "次期計画では実績に基づく見込量を設定してください。"
                  "③成年後見制度法人後見支援事業及び手話奉仕員養成研修事業は、"
                  "現行計画の事業内容欄には記載がありますが、実績・見込量の表に行がありません。"
                  "表に加えるか、実施しない旨を明記するかを整理してください。"
                  "④地域生活支援事業は国２分の１以内・県４分の１以内の統合補助金による"
                  "裁量的経費です。事業別の事業費、国県補助額、村負担額、"
                  "補助基準額の超過の有無をご提供ください。"),
        make_empty(doc),
    ])
    changes.append("第5章9：地域生活支援事業に「事業ごとの実施に関する考え方」"
                   "（告示第三の二の3㈡）を追加し、移動支援0人・福祉ホームの実績と見込の"
                   "逆転・見込量表に行がない2事業を確認事項として明記")


def add_katsudou_shihyou(doc):
    """第5章に「活動指標」の節を新設する（仕様書4-Ⅱ(3)⑤。骨子案に欠落）。

    告示 第三 四 ㈡ により、サービスの見込量以外の活動指標は任意である。
    見込量に相当するものは第5章の見込量表がそのまま活動指標となるため、
    ここでは任意分のうち本村が設定するものを表として掲げる。
    """
    anchor = find_para(doc, "10　事業提供体制の確保のための方策", style="Heading 2")
    insert_before(anchor, [
        make_para(doc, "10　活動指標", style="Heading 2"),
        make_para(doc,
                  "国の基本指針は、成果目標を達成するために必要な量等を「活動指標」として"
                  "計画に見込むことが適当であるとしています（第二）。"
                  "活動指標の項目は基本指針の別表第一に定められており、"
                  "このうちサービスの見込量に相当するものは本章３から８までに掲げた見込量が"
                  "そのまま活動指標となります。"
                  "サービスの見込量以外の活動指標については、"
                  "地方公共団体の実情に応じて任意に定めることができるとされています"
                  "（第三の四㈡）。"),
        make_para(doc,
                  "本村では、村内に障害者支援施設がないこと、"
                  "相談支援・発達障がい支援の専門機関が県又は圏域に置かれていることを踏まえ、"
                  "次の項目を活動指標として設定します。"),
        make_para(doc, "■　サービスの見込量に相当する活動指標", style="Heading 3"),
        make_para(doc,
                  "本章３（訪問系サービス）、４（日中活動系サービス）、５（居住系サービス）、"
                  "６（相談支援）、７（障がい児支援）に掲げる見込量が活動指標を兼ねます。"
                  "対象は居宅介護、重度訪問介護、同行援護、行動援護、重度障害者等包括支援、"
                  "生活介護、自立訓練（機能訓練・生活訓練）、就労選択支援、就労移行支援、"
                  "就労継続支援（Ａ型・Ｂ型）、就労定着支援、療養介護、短期入所（福祉型・医療型）、"
                  "自立生活援助、共同生活援助、施設入所支援、計画相談支援、地域移行支援、"
                  "地域定着支援、児童発達支援、放課後等デイサービス、保育所等訪問支援、"
                  "居宅訪問型児童発達支援及び障害児相談支援です。"),
        make_para(doc, "■　その他の活動指標", style="Heading 3"),
        make_table(doc, [
            ["区分", "活動指標", "単位", "令和６年度\n実績", "令和11年度\n見込"],
            ["精神障害にも対応した\n地域包括ケアシステム",
             "保健・医療・福祉関係者による協議の場の開催回数", "回／年", "【要更新】", "【要検討】"],
            ["", "協議の場への関係者の参加者数", "人／回", "【要更新】", "【要検討】"],
            ["", "協議の場における目標設定及び活動状況の把握・評価", "有無", "【要更新】", "実施"],
            ["", "心のサポーター養成研修の実施回数【新規】", "回／年", "０", "【要検討】"],
            ["", "精神障がい者の地域移行支援・地域定着支援・共同生活援助・"
                 "自立生活援助・自立訓練（生活訓練）・短期入所の利用者数",
             "人／月", "【要更新】", "【要検討】"],
            ["地域生活支援の充実", "地域生活支援拠点等の設置箇所数", "か所", "１", "１"],
            ["", "拠点コーディネーターの配置人数", "人", "１", "１"],
            ["", "運用状況の検証・検討の実施回数", "回／年", "【要更新】", "１回以上"],
            ["障がい児支援",
             "医療的ケア児等に対する関連分野の支援を調整するコーディネーターの配置人数",
             "人", "【要更新】", "１"],
            ["相談支援体制の\n充実・強化等", "協議会の実施回数、専門部会の設置数及び実施回数",
             "回・か所", "【要更新】", "【要検討】"],
            ["", "個別事例の検討を通じて抽出された課題を協議会の議題とした数",
             "件／年", "【要更新】", "【要検討】"],
            ["障がい福祉サービス等の\n質の向上",
             "県が実施する障がい福祉サービス等に係る研修への村職員の参加人数",
             "人／年", "【要更新】", "【要検討】"],
            ["", "障害者自立支援審査支払等システム等による審査結果を分析・共有する体制の"
                 "有無及び実施回数", "有無・回", "【要更新】", "【要検討】"],
        ], [1900, 3400, 1100, 1600, 1638]),
        make_para(doc, "■　本村では設定しない活動指標", style="Heading 3"),
        make_para(doc,
                  "別表第一に掲げられた活動指標のうち、次の項目は本村の実情から設定しません。"
                  "施設における居室の個室化等の取組状況及び意向確認担当者の地域生活への移行に"
                  "向けた支援回数は、いずれも障害者支援施設の取組を測る指標であり、"
                  "本村に施設がないためです（ただし、施設入所者の意向を協議の場において"
                  "共有することは本村の役割として第４章（１）に位置づけています）。"
                  "精神保健福祉相談員講習会等の実施回数、発達障害者支援地域協議会の開催回数及び"
                  "発達障害者支援センターに関する各指標は、県又は圏域の機関が実施主体であるためです。"),
        make_note(doc,
                  "【要更新・要確認】上表の令和６年度実績は村の記録から把握してください。"
                  "また「本村では設定しない」とした項目について、村としての判断を確定してください。"
                  "設定するか否かを明記しないと、検討漏れと区別がつきません。"
                  "なお、基本指針は成果目標及び活動指標に加えて独自に目標及び指標を設定することが"
                  "できるとしています（第二）。本村では中山間・人口減少地域としての課題を踏まえ、"
                  "圏域の事業所の受入可能性に関する指標（例：訪問系サービスを提供する事業所数）を"
                  "独自指標として設定することも考えられます。"),
        make_empty(doc),
    ])
    renumber_heading(doc, "10　事業提供体制の確保のための方策",
                     "11　事業提供体制の確保のための方策")
    renumber_heading(doc, "11　障がい福祉サービス等に係る費用の推移と財源構成",
                     "12　障がい福祉サービス等に係る費用の推移と財源構成")
    changes.append("第5章：「10　活動指標」を新設（仕様書4-Ⅱ(3)⑤。骨子案に欠落していた項目。"
                   "既存の10〜11を11〜12へ繰り下げ）")


# ---------------------------------------------------------------------------
# 村がアンケート調査票の朱書きで提供した実データの反映
# 出所は docs/北塩原村_アンケート調査票_村修正指示_確認結果.md、
# 整理は output/北塩原村_村提供実績データ.xlsx。
# 村が「この設問は不要」と判断した理由として書き添えた数値であり、
# 基準日が明示されていないものは注記で照会事項として残す。
# ---------------------------------------------------------------------------

# 障害支援区分別人数（障がい者版 問7 の朱書き）
KUBUN_NINZU = [("区分１", 0), ("区分２", 5), ("区分３", 2),
               ("区分４", 5), ("区分５", 1), ("区分６", 2)]


def add_kubun_verification(doc):
    """第5章1の推計方法に、障害支援区分別人数による見込量の検証を追加する。

    add_estimation_basis が挿入した「■　算定方法の根拠となる基本指針の規定」の
    直後に置くため、main() では add_estimation_basis の後に呼ぶ。
    """
    total = sum(n for _k, n in KUBUN_NINZU)
    assert total == 15, f"区分別人数の合計が15人と一致しない: {total}"

    anchor = find_para(doc, "■　算定方法の根拠となる基本指針の規定", style="Heading 3")
    kubun_tbl = [["障害支援区分", "人数", "支給決定の要件となる主なサービス"]]
    youken = {
        "区分１": "居宅介護",
        "区分２": "居宅介護、短期入所、生活介護（50歳以上）",
        "区分３": "生活介護、短期入所、施設入所支援（50歳以上）、行動援護",
        "区分４": "生活介護、施設入所支援、重度訪問介護",
        "区分５": "生活介護、施設入所支援、重度訪問介護",
        "区分６": "生活介護、施設入所支援、重度訪問介護、行動援護",
    }
    for k, n in KUBUN_NINZU:
        kubun_tbl.append([k, f"{n}人", youken[k]])
    kubun_tbl.append(["合計", f"{total}人", "―"])

    kensho_tbl = [
        ["検証の観点", "内容", "判定"],
        ["区分４以上（８人）と施設入所支援（４人）",
         "施設入所支援は原則として区分４以上（50歳以上は区分３以上）が支給決定の要件です。"
         "区分４以上８人のうち４人が施設入所支援を利用している計算となり、矛盾しません。"
         "残る４人は在宅で生活介護等を利用しているとみられます。", "整合"],
        ["区分３以上（10人）と生活介護（６人）",
         "生活介護は原則として区分３以上（50歳以上は区分２以上）が支給決定の要件です。"
         "区分３以上10人のうち６人が生活介護を利用している計算となり、矛盾しません。", "整合"],
        ["区分認定者（15人）と計画相談支援（22人）",
         "計画相談支援は訓練等給付（就労継続支援Ｂ型等）の利用者も対象であり、"
         "これらは区分認定を要しません。就労継続支援Ｂ型11人を加えると26人となり、"
         "22人はその範囲内にあります。", "整合"],
        ["区分認定者（15人）と共同生活援助（８人）",
         "共同生活援助は障害支援区分の認定を必ずしも要しません。"
         "施設入所支援４人・生活介護６人・居宅介護４人の計14人（重複を含む）に対し"
         "区分認定者が15人であることから、共同生活援助の利用者の相当部分は"
         "区分認定を受けていないと推定されます。", "要確認"],
    ]

    insert_after(anchor, [
        make_para(doc, "■　障害支援区分別人数による見込量の検証", style="Heading 3"),
        make_para(doc,
                  "本村において障害支援区分の認定を受けている方は15人です。"
                  "障害支援区分は介護給付（居宅介護、生活介護、短期入所、施設入所支援等）の"
                  "支給決定に必要な手続きであり、訓練等給付（就労継続支援等）や"
                  "共同生活援助の一部は認定を要しません。したがってこの15人は"
                  "「介護給付の対象となる方の数」であり、サービス利用者の総数ではありません。"),
        make_table(doc, kubun_tbl, [1800, 1200, 6638]),
        make_para(doc,
                  "この区分別人数を、本章３以下の見込量と突き合わせると次のとおりです。"),
        make_table(doc, kensho_tbl, [2600, 6038, 1000]),
        make_para(doc,
                  "いずれの観点でも見込量との矛盾はなく、本章の個別積上げ方式による"
                  "推計値は区分別人数の裏づけを得ています。あわせて、実績のない"
                  "重度訪問介護（区分４以上が要件）及び行動援護（区分３以上かつ"
                  "行動関連項目10点以上が要件）についても、対象要件を満たす方が"
                  "本村に在籍していることが確認できました。本章では、実績がないことを"
                  "もってニーズがないとは判断せず、これらのサービスを見込量表に"
                  "掲げたうえで、支給決定の要件と利用の可否を記載します。"),
        make_note(doc,
                  "【要確認：村】①障害支援区分15人の基準日（令和７年４月１日時点か直近か）を"
                  "確認してください。②15人それぞれのサービス利用状況が分かると、"
                  "介護給付の見込量を区分別に積み上げて検証できます。"
                  "③区分６の２人について行動関連項目の点数を確認してください。"
                  "強度行動障害の状態にある方の支援ニーズ把握（第８期の新規視点）と"
                  "行動援護の対象該当性の判断に用います。"
                  "④共同生活援助の利用者のうち区分認定を受けている方の数を確認してください。"),
        make_empty(doc),
    ])
    changes.append("第5章1：障害支援区分別人数（15人）による見込量の検証を追加")


def apply_village_data(doc):
    """第4章の成果目標に、村から提供された実データを反映する。"""

    # （３）福祉施設から一般就労への移行等 ── 就労選択支援の事業所がない
    anchor = find_para(doc, "本村には就労継続支援事業所がなく")
    insert_after(anchor, [
        make_para(doc,
                  "就労選択支援については、会津管内に事業所が設置されていないことを"
                  "村に確認しています。基本指針は、令和11年度末までに各市町村又は各圏域に"
                  "１事業所以上の設置を目指すとしていることから、本村単独での確保ではなく、"
                  "会津若松地方の広域調整により圏域内での確保を図ることを"
                  "第５章の提供体制の確保のための方策に位置づけます。"),
    ])
    changes.append("第4章（３）：会津管内に就労選択支援事業所がないことと圏域確保の方針を追加")

    # （４）障がい児支援の提供体制の整備等 ── 医療的ケア児1名の状態像
    anchor = find_para(doc, "また、令和８年度に設置予定の「こども家庭センター」")
    insert_after(anchor, [
        make_para(doc,
                  "医療的ケア児については、本村に１人おり、経管栄養が毎日必要な状態に"
                  "あることを村に確認しています。対象となる児童が１人であっても、"
                  "基本指針が求める医療的ケア児等に対する関係機関の協議の場の設置と"
                  "医療的ケア児等コーディネーターの配置は必要です。日常的に医療的ケアを要する"
                  "状態であることから、訪問看護、通園・通学先での医療的ケア体制、"
                  "災害時の電源・医療機器の確保を含めて、保健・医療・福祉・保育・教育の"
                  "関係機関が情報を共有できる体制を整えます。"),
        make_para(doc,
                  "なお、障がい児入所施設及び児童福祉施設に入所している児童は０人、"
                  "障害児通所支援の支給決定の申請中の児童も０人であることを"
                  "村に確認しています。第５章の障害児入所支援の見込量を０とする根拠は"
                  "この確認によります。"),
        make_note(doc,
                  "【要確認：村】医療的ケア児１人の年齢と就学状況を確認してください。"
                  "本章の記載のほか、第５章２の年齢到達に伴うサービスの移行（18歳到達時期）の"
                  "見通しに用います。"),
    ])
    changes.append("第4章（４）：医療的ケア児1人（経管栄養が毎日必要）の状態像と、"
                   "障がい児入所0人・通所支援申請中0人を追加")

    # （６）相談支援体制の充実・強化等 ── 基幹相談支援センター未設置・セルフプラン0％
    anchor = find_para(doc, "「のぞまないセルフプラン」とは")
    insert_after(anchor, [
        make_para(doc,
                  "本村のセルフプラン率は０％であり、サービス等利用計画及び"
                  "障がい児支援利用計画はすべて相談支援専門員が作成しています。"
                  "したがって「のぞまないセルフプラン」は本村には存在せず、"
                  "第８期の成果目標は、令和11年度末まで０を維持することとします。"),
        make_para(doc,
                  "基幹相談支援センターについては、令和８年８月時点で未設置であることを"
                  "村に確認しています。第７期計画は令和８年度末までに１か所の設置を"
                  "目標としていましたが、達成に至っていません。基本指針は令和11年度末までの"
                  "設置を成果目標としていることから、猪苗代町・磐梯町・湯川村との"
                  "広域設置の検討状況を踏まえ、目標年次を改めて設定します。"),
        make_note(doc,
                  "【要確認：村】基幹相談支援センターについて、第８期計画期間中の設置意向と、"
                  "４町村での広域設置の検討状況を確認してください。"
                  "設置が見込めない場合は「設置に向けた検討を進める」ことを目標に据えるなど、"
                  "実態に即した目標設定に改めます。"),
    ])
    changes.append("第4章（６）：セルフプラン率0％と基幹相談支援センター未設置を追加")


def fix_shokan_ka(doc):
    """奥付の編集所管課を「保健福祉課福祉係」に確定する。

    村がアンケート調査票の朱書きで、問合せ先を「医療福祉班」から
    「保健福祉課 福祉係」に修正したことにより、所管課が確定した。
    """
    tbl = find_table(doc, "【要更新・要確認】本計画書の編集所管課の表記を確認してください。")
    if tbl is None:
        return
    set_box_lines(doc, tbl, [
        "【確認済み】本計画書の編集所管課は「北塩原村 保健福祉課 福祉係」です。"
        "令和８年８月に村からアンケート調査票の修正指示を受けた際、"
        "問合せ先の表記が「医療福祉班」から「保健福祉課 福祉係」に修正されたことにより"
        "確定しました。業務委託仕様書の事務担当の記載とも一致します。"
        "現行計画において障がい者相談支援事業の実施主体を住民課としている記載は、"
        "組織改編前のものとして整理します。",
    ])
    changes.append("奥付：編集所管課を「保健福祉課福祉係」に確定（村の修正指示による）")


