def add_pdca_detail(doc):
    """第1章6の計画の推進体制に、PDCAの実施体制・スケジュール・公表・管理シートを追加する。"""
    # 「６　計画の推進体制」の本文段落の直後にある PDCA の4段階表の後ろへ挿入する
    intro = find_para(doc, "障害者総合支援法においては、計画に定める事項について")
    anchor = find_block_after(doc, intro, "tbl")

    taisei = [
        ["区分", "担い手", "役割"],
        ["庁外", "北塩原村障がい者自立支援協議会",
         "成果目標及び活動指標の実績に対する評価と意見。中間評価の結果の確認"],
        ["庁内", "保健福祉課 福祉係（計画の所管）",
         "実績の把握、分析・評価の取りまとめ、協議会への報告、改善方策の立案"],
        ["庁内", "関係各課（住民課、教育委員会、総務課（防災）ほか）",
         "所管する事業の現状分析と、改善に向けた取組の検討"],
    ]

    schedule = [
        ["時期", "取組"],
        ["各年度 4〜6月", "前年度の成果目標及び活動指標の実績を把握し、分析・課題の整理を行う"],
        ["各年度 7〜9月", "自立支援協議会へ実績と評価案を報告し、意見を聴く"],
        ["各年度 10〜12月",
         "協議会の意見を踏まえて改善方策を検討し、次年度の予算要求に反映する"],
        ["各年度 1〜3月", "次年度の取組を協議会へ報告する。中間評価の結果を公表する"],
    ]

    kanri = [
        ["区分", "記載する内容"],
        ["計画（Plan）・実施（Do）",
         "成果目標の目標値と設定の考え方、年度別の目標、前期計画での実績（参考）、"
         "主な活動指標の見込量と実績"],
        ["評価（Check）", "目標等を踏まえた評価と改善方策の案"],
        ["協議会等意見", "評価等に対する自立支援協議会の意見"],
        ["改善（Act）", "次年度における取組等"],
    ]

    insert_after(anchor, [
        make_para(doc, "■　評価の体制", style="Heading 3"),
        make_para(doc,
                  "計画の内容は障がい福祉分野だけでなく、保健、医療、教育、就労、防災など"
                  "様々な分野に関わります。庁内の関係各課と、障がい当事者や事業者を含む"
                  "自立支援協議会とが、それぞれの役割を分けたうえで連携して評価を行います。"),
        make_table(doc, taisei, [1200, 3400, 5038]),
        make_para(doc,
                  "計画の策定に関わった方に評価にも関わっていただくことで、"
                  "進行管理の一貫性を保ちます。"),
        make_para(doc, "■　評価のスケジュール", style="Heading 3"),
        make_para(doc,
                  "評価の結果を次年度の取組に反映させるため、"
                  "村の予算編成の時期に合わせて次の日程で進めます。"),
        make_table(doc, schedule, [2400, 7238]),
        make_para(doc,
                  "成果目標及び活動指標は少なくとも年１回実績を把握します。"
                  "このうち活動指標については、サービスの利用実績が国民健康保険団体連合会の"
                  "給付実績データにより把握できることから、より高い頻度で実績を確認し、"
                  "見込量との差が大きくなっていないかを点検します。"),
        make_para(doc, "■　目標等の管理シート", style="Heading 3"),
        make_para(doc,
                  "成果目標ごとに、目標値と設定の考え方、対応する活動指標の見込量と実績、"
                  "評価、協議会の意見、次年度の取組を１枚にまとめた管理シートを作成し、"
                  "年度ごとに記録します。第９期計画の策定時に、"
                  "本計画期間中の評価と改善の経過をそのまま参照できるようにするためです。"),
        make_table(doc, kanri, [3000, 6638]),
        make_para(doc, "■　結果の公表", style="Heading 3"),
        make_para(doc,
                  "中間評価の結果は、障がいのある方やサービス事業者だけでなく、"
                  "広く村民に向けて公表します。村のホームページ及び広報誌に掲載するほか、"
                  "自立支援協議会で使用した資料もできる限り公開します。"
                  "公表にあたっては、読み上げソフトに対応した形式とするなど、"
                  "情報を得やすくするための配慮を行います。"),
        make_note(doc,
                  "【確認済み】本節は「障害福祉計画策定に係る実態調査及びPDCAサイクルに関する"
                  "マニュアル」（令和８年８月。厚生労働省社会・援護局障害保健福祉部企画課、"
                  "こども家庭庁支援局障害児支援課）Ⅱに沿って記載しています。"
                  "福島県は令和８年８月24日付け８生福第2646号・８こ第2041号により"
                  "市町村へ通知しています。"),
        make_note(doc,
                  "【要確認：村】①評価の体制について、自立支援協議会と庁内の会議体の"
                  "役割分担を確認してください。②評価のスケジュールは村の予算編成の時期に"
                  "合わせる必要があるため、実際の日程をご教示ください。"
                  "③中間評価の結果の公表方法（ホームページ、広報誌、協議会資料の公開範囲）を"
                  "確認してください。"),
        make_empty(doc),
    ])
    changes.append("第1章6：PDCAの評価体制・スケジュール・管理シート・結果の公表を追加"
                   "（実態調査及びPDCAサイクルに関するマニュアル 令和8年8月）")


def add_manual_comparison(doc):
    """第5章1の推計方法に、マニュアルが示す2方式との比較を追加する。"""
    anchor = find_para(doc, "■　障害支援区分別人数による見込量の検証", style="Heading 3")
    if anchor is None:
        return

    hikaku = [
        ["推計方法", "内容", "本村での適否"],
        ["①　過去のサービス量実績値の変化率の平均を用いる方法",
         "過去の実績値から年ごとの変化率を求め、その幾何平均を直近の実績値に乗じて"
         "各年度の見込量を算出する。多くの市町村が採用している。",
         "適さない。マニュアルは、実績値が小さい場合は「実績値の変化により推計値の値が"
         "変化しやすい」、実績値が極端に増減している場合は幾何平均による算出で"
         "「２年後、３年後の推計値が過大（過少）に推計されてしまう可能性がある」と"
         "留意点を示している。本村は利用者１人が生活介護で16.7％、"
         "居宅介護・施設入所支援で25％を占めるため、この留意点が正面から当てはまる。"],
        ["②　人口当たり利用率を用いる方法",
         "現在のサービス利用者数を人口で除して利用率を求め、"
         "将来推計人口に乗じて見込量を算出する。人口の変動を反映しやすい。",
         "補助的に用いる。本村の人口は令和６年の2,394人から令和11年に向けて"
         "減少が見込まれるため、利用率を一定とすると見込量も減少する。"
         "しかし手帳所持者数は人口ほどには減っておらず、"
         "利用率そのものが上昇している。本方式は第２章の手帳所持者数の"
         "将来推計で用い、見込量の推計では検証手段として位置づける。"],
        ["③　基準年度の水準の維持＋成果目標による個別補正（本計画の見込量）",
         "給付実績が完結した直近の年度（令和７年度）の水準を維持し、"
         "成果目標で人数が定まるサービスと、実績があるのに０となるサービスだけを"
         "個別に補正する。",
         "採用する。①②がいずれも本村の規模では成り立たないためである。"
         "マニュアルは「計画期間の最終年度は見込量推計を行う時点で実績値が"
         "確定していないことから、当該年度のデータを推計に用いることが難しい」と"
         "しており、令和８年度ではなく令和７年度を基準年度とした。"
         "第５章３から７に掲げる値はこの方法によるものであり、本計画の見込量とする。"],
        ["④　個別積上げ方式（第２次算定の方法）",
         "利用者ごとに、継続、新規、年齢到達による流入、地域移行、"
         "介護保険等への移行、一般就労、転出等を１人単位で加減算し、"
         "１人当たり月利用量を乗じて月間サービス量を算出する。",
         "村から年齢別・サービス別の匿名利用者一覧及び支給決定者数（実人数）を"
         "受領した後に行う。基本指針 別表第一が勘案を求める「現に利用している者の数」"
         "「障がい者等のニーズ」「平均的な一人当たり利用量」をそのまま積み上げる方法であり、"
         "利用者が各サービス数人規模の本村の実情に最も適合する。"
         "あわせてアンケート調査の「現在の利用」と「今後３年間の利用希望」を重ね、"
         "見込量を確定する（上記マニュアルP.26の参考手順）。"],
    ]

    insert_before(anchor, [
        make_para(doc, "■　国が示す推計方法との関係", style="Heading 3"),
        make_para(doc,
                  "「障害福祉計画策定に係る実態調査及びPDCAサイクルに関するマニュアル」"
                  "（令和８年８月。令和８年８月19日付け厚生労働省社会・援護局障害保健福祉部企画課・"
                  "こども家庭庁支援局障害児支援課事務連絡により発出）は、実績値に基づく"
                  "サービス見込量の推計方法として次の２つを示しています。"
                  "本計画がこれらを採らなかった理由と、採った方法をあわせて整理します。"),
        make_table(doc, hikaku, [2400, 3400, 3838]),
        make_note(doc,
                  "【確認済み】上記マニュアルP.22の「③地域差の是正について」手順Ⅰは、"
                  "要件１（全部過疎市町村でないこと）と要件２（当該サービスの人口に占める"
                  "サービス利用割合が要件１を満たす市町村の上位25％の範囲内であること）の"
                  "「両方に該当しない場合は、18ページの内容を参考として、"
                  "サービスに必要な見込量を算出してください」としています。"
                  "本村は全部過疎市町村であるため要件１に該当せず、"
                  "地域差是正の算定方法は適用されません。"
                  "なお、同マニュアルは地域差是正の対象を生活介護、就労継続支援Ａ型、"
                  "就労継続支援Ｂ型、児童発達支援、放課後等デイサービス、共同生活援助の"
                  "６サービスと明示しています。"),
        make_empty(doc),
    ])
    changes.append("第5章1：国が示す推計方法（変化率の平均・人口当たり利用率）との比較を追加。"
                   "本計画の見込量は基準年度（令和7年度）の水準の維持＋成果目標による補正に"
                   "よるものであること、個別積上げは村資料受領後の第2次算定の方法であることを"
                   "正本として明記")



