# ---------------------------------------------------------------------------
# 骨子案レビュー（docs/北塩原村_骨子案レビュー_基本指針網羅性確認.md）で
# 優先度「高」とした4件の反映。
#
#   R-1 人材確保、ケアの充実のための生産性向上及び経営基盤の確立等に係る取組事項
#       別表第二 六の項（令和8年7月10日の改正Bで新設。定めるよう努める事項）
#   R-2 長期入院患者の地域生活への移行に伴う地域の精神保健医療福祉体制の基盤整備量
#       別表第二 三㈠⑤（定めなければならない事項）
#   R-3 医療的ケア児等（医療的ケア者を含む）への対応
#       令和8年8月19日の改正C 全般
#   R-4 関係機関との連携に関する事項
#       別表第二 五㈠（定めるよう努める事項）
# ---------------------------------------------------------------------------

def find_table_where(doc, row, col, prefix):
    """指定のセルが指定の文字列で始まる表を返す。先頭セルだけでは特定できない表用。"""
    for child in doc.element.body.iterchildren():
        if child.tag != qn("w:tbl"):
            continue
        t = Table(child, doc)
        if len(t.rows) > row and len(t.columns) > col \
                and t.cell(row, col).text.strip().startswith(prefix):
            return child
    raise LookupError(f"表が見つかりません: ({row},{col})={prefix!r}")


def append_table_row(doc, tbl_element, values):
    """既存の表の書式を保ったまま、末尾に1行足す。

    最終行を複製し、各セルの本文だけを差し替える。
    """
    t = Table(tbl_element, doc)
    last = t.rows[-1]._tr
    new = copy.deepcopy(last)
    last.addnext(new)
    row = t.rows[-1]
    for cell, text in zip(row.cells, values):
        paras = cell.paragraphs
        for extra in paras[1:]:
            extra._p.getparent().remove(extra._p)
        p = paras[0]
        for run in list(p.runs):
            run._r.getparent().remove(run._r)
        run = p.add_run(text)
        _set_font(run, size=10)
    return new


