def _per_capita():
    """1人当たり月利用量（現行計画の令和8年度見込量による）。"""
    from kitashiobara_common import SERVICES_ADULT, SERVICES_CHILD
    out = {}
    for src in (SERVICES_ADULT, SERVICES_CHILD):
        for name, _u, _q, _users, _qty, per, _note in src:
            out[name] = per
    # 概算の表記に合わせる
    out["就労継続支援Ａ型"] = out.get("就労継続支援A型", 0.0)
    out["就労継続支援Ｂ型"] = out.get("就労継続支援B型", 0.0)
    out["障がい児相談支援"] = out.get("障がい児相談支援", 0.0)
    return out


