def fix_section_refs(doc):
    """本文中の第5章の節番号の参照ずれを直す。"""
    hits = {old: 0 for old, _ in SECTION_REF_FIXES}
    for para in iter_all_paragraphs(doc):
        for old, new in SECTION_REF_FIXES:
            for run in para.runs:
                if old in run.text:
                    run.text = run.text.replace(old, new)
                    hits[old] += 1
    missing = [old for old, n in hits.items() if n == 0]
    if missing:
        raise LookupError(f"節番号の参照ずれが見つかりません: {missing}")
    changes.append(f"本文：第5章の節番号の参照ずれを{sum(hits.values())}か所修正"
                   "（地域生活支援事業は第5章9、障がい児支援は第5章7）")


