# 「法定雇用率2.7％への引上げ（令和８年７月）」を巻き込まないため）
DATE_EDITS = [
    ("令和８年７月", "令和８年９月"),
    ("作成日：令和８年７月", "作成日：令和８年９月"),
]


def iter_all_paragraphs(doc):
    """本文・表中を問わず、すべての段落を返す。"""
    for child in doc.element.body.iterchildren():
        if child.tag == qn("w:p"):
            yield Paragraph(child, doc)
        elif child.tag == qn("w:tbl"):
            for row in Table(child, doc).rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        yield para


def fix_title(doc):
    """表紙・前書き・奥付の「骨子案」「ドラフト」の表記を「素案」に改める。"""
    hits = {old: 0 for old, _ in TITLE_EDITS}
    hits.update({old: 0 for old, _ in DATE_EDITS})

    for para in iter_all_paragraphs(doc):
        full = para.text.strip()
        for old, new in DATE_EDITS:
            if full == old:
                for run in para.runs:
                    if old in run.text:
                        run.text = run.text.replace(old, new)
                        hits[old] += 1
                break
        for old, new in TITLE_EDITS:
            for run in para.runs:
                if old in run.text:
                    run.text = run.text.replace(old, new)
                    hits[old] += 1

    missing = [old for old, n in hits.items() if n == 0]
    if missing:
        raise LookupError(f"表題の置換対象が見つかりません: {missing}")

    changes.append("表紙・前書き・奥付：表題を「骨子案」から「素案」に変更し、"
                   "作成年月を令和８年９月、編集所管課を保健福祉課福祉係に更新")


def verify_service_names():
    """体系表のサービス名が管理ブックの区分から外れていないかを確かめる。"""
    from kitashiobara_common import SERVICES_ADULT, SERVICES_CHILD, SERVICES_ZERO
    known = set()
    for src in (SERVICES_ADULT, SERVICES_CHILD, SERVICES_ZERO):
        for rec in src:
            known.add(rec[0])
    # 表記のゆれを吸収して突合する
    alias = {
        "居宅介護（ホームヘルプ）": "居宅介護",
        "短期入所（ショートステイ）": "短期入所（福祉型）",
        "自立訓練（機能訓練・生活訓練）": "自立訓練（生活訓練）",
        "就労継続支援Ａ型": "就労継続支援A型",
        "就労継続支援Ｂ型": "就労継続支援B型",
        "共同生活援助（グループホーム）": "共同生活援助",
        "重度障害者等包括支援": "重度障がい者等包括支援",
    }
    skip = {"自立支援医療", "補装具費", "障害児入所支援",
            "相談支援、意思疎通支援、日常生活用具給付等、移動支援ほか",
            "訪問入浴サービス、日中一時支援、福祉ホームほか"}
    for _kubun, name, _naiyo in SERVICE_TAIKEI:
        if name in skip:
            continue
        key = alias.get(name, name)
        assert key in known, f"体系表のサービス名が管理ブックにありません: {name}"
    # 廃止済みのサービスを載せていないこと
    names = {n for _k, n, _v in SERVICE_TAIKEI}
    assert "医療型児童発達支援" not in names, "医療型児童発達支援は一元化済みです"
    # 用語の重複がないこと
    terms = [t for t, _ in YOUGO]
    assert len(terms) == len(set(terms)), "用語解説に重複があります"


