KEN_DIR = f"{REPO_ROOT}/source/県計画"
KEN_TXT = (f"{KEN_DIR}/"
           f"第7期福島県障がい福祉計画_第3期障がい児福祉計画_本文テキスト.txt")
KEN_GAIYOU = [
    f"{KEN_DIR}/第7期福島県障がい福祉計画_概要_625509.pdf",
    f"{KEN_DIR}/第3期福島県障がい児福祉計画_概要_625510.pdf",
]
KEN_SHOGAISHA_TXT = f"{KEN_DIR}/第5次福島県障がい者計画_本文テキスト.txt"
KEN_PDF_TEXT = ""


def _norm_ken(s):
    """照合用に空白と全角数字・記号のゆれを落とす。"""
    z = "０１２３４５６７８９"
    for i, c in enumerate(z):
        s = s.replace(c, str(i))
    s = s.replace("，", ",").replace("．", ".").replace("％", "%")
    s = s.replace("：", ":").replace("　", "")
    return re.sub(r"[\s,]", "", s)


def load_ken_pdf():
    """県計画（本文・本文テキスト・概要2点）を1つの照合用文字列にまとめる。

    本文テキスト（県が公開しているテキスト版）はPDFの抽出より崩れが少ないため、
    文章の照合に用いる。概要2点には本文の表にない集計値（県全体の59市町村・
    39か所・218人等）が載っているため、数値の照合に用いる。
    """
    global KEN_PDF_TEXT
    import pypdf
    parts = []
    for path in [KEN_PDF] + KEN_GAIYOU:
        if not os.path.exists(path):
            raise SystemExit(
                f"県計画が見つかりません: {path}\n"
                "第1章2・第4章（4）（6）・第5章8はこの原典から引いています。")
        r = pypdf.PdfReader(path)
        parts.append("".join((p.extract_text() or "") for p in r.pages))
    for path in (KEN_TXT, KEN_SHOGAISHA_TXT):
        if not os.path.exists(path):
            raise SystemExit(f"県計画の本文テキストが見つかりません: {path}")
        with open(path, encoding="utf-8") as fh:
            parts.append(fh.read())
    KEN_PDF_TEXT = _norm_ken("\n".join(parts))
    return KEN_PDF_TEXT


MURA_MOKUHYO_PDF = (f"{REPO_ROOT}/source/村資料_自立支援協議会_20260525/"
                    f"障害福祉サービス等の提供体制の確保に係る目標.pdf")


def read_mura_mokuhyo():
    """村が公表した成果目標の進捗を読む。

    令和8年5月25日の北塩原村障がい者自立支援協議会の資料。
    項目名 → 令和5・6・7年度の値（文字列）。
    """
    import pdfplumber
    if not os.path.exists(MURA_MOKUHYO_PDF):
        raise SystemExit(
            f"村資料が見つかりません: {MURA_MOKUHYO_PDF}\n"
            "第4章の実績は令和8年5月25日の自立支援協議会の資料によります。")
    out = {}
    with pdfplumber.open(MURA_MOKUHYO_PDF) as pdf:
        for page in pdf.pages:
            for tbl in page.extract_tables():
                for row in tbl:
                    c = ["" if x is None else x.replace("\n", "").strip()
                         for x in row]
                    label = next((v for v in c if len(v) > 5
                                  and "目標設定" not in v
                                  and "項目" not in v), "")
                    if not label:
                        continue
                    vals = [v for v in c if v and v != label]
                    if len(vals) >= 4:
                        out[label] = vals[-4:]
    if len(out) < 10:
        raise SystemExit(f"村の成果目標を読めていません: {len(out)}件")
    return out


def apply_mura_jisseki(doc):
    """第4章の【要更新】を、村が公表した令和5〜7年度の進捗で埋める。

    原本（他メンバー作成）は実績を【要更新】としていた。令和8年10月8日に
    村資料（令和8年5月25日 自立支援協議会）を受領したため、
    PDFから読んだ値で置き換える。数値は書き写さない。
    """
    m = read_mura_mokuhyo()

    def val(key, i):
        for label, vals in m.items():
            if key in label:
                return vals[i]
        raise LookupError(f"村資料に項目が見つかりません: {key}")

    # 施設入所者数（R5・R6・R7）
    nyusho = [val("施設入所者数", i) for i in (1, 2, 3)]
    taiin = [val("長期入院患者の退院者数", i) for i in (1, 2, 3)]
    ippan = [val("一般就労への移行者数", i) for i in (1, 2, 3)]
    teichaku = [val("就労定着支援事業の利用者数", i) for i in (1, 2, 3)]
    kikan = [val("基幹相談支援センターの設置数", i) for i in (1, 2, 3)]
    kenshu = [val("村職員の参加人数", i) for i in (1, 2, 3)]

    reps = [
        ("【要更新】\n（参考：R5末 4人）",
         f"{nyusho[2]}人\n（令和５〜７年度とも{nyusho[2]}人）"),
        ("精神病床に１年以上入院する患者の退院者数。前期目標を継続。実績【要更新】",
         f"精神病床に１年以上入院する患者の退院者数。前期目標を継続。"
         f"実績は令和５年度{taiin[0]}人・令和６年度{taiin[1]}人・"
         f"令和７年度{taiin[2]}人で未達"),
        ("令和６年度実績【要更新】の1.31倍以上を踏まえて設定",
         f"実績は令和５年度{ippan[0]}人・令和６年度{ippan[1]}人・"
         f"令和７年度{ippan[2]}人。令和７年度に前期目標１人を達成した"),
        ("令和６年度実績【要更新】の1.47倍以上を踏まえて設定",
         f"実績は令和５年度{teichaku[0]}人・令和６年度{teichaku[1]}人・"
         f"令和７年度{teichaku[2]}人で未達"),
        ("令和８年度末までの検討状況を踏まえ、令和11年度末までの設置を目指す【要更新】",
         f"令和５〜７年度の実績は{kikan[2]}か所で未達。"
         f"令和８年度末までの検討状況を踏まえ、令和11年度末までの設置を目指す"),
        ("令和４年度実績１人から拡充（第４次計画（７）の目標を継承）",
         f"実績は令和５年度{kenshu[0]}人・令和６年度{kenshu[1]}人・"
         f"令和７年度{kenshu[2]}人。令和６年度に前期目標２人を達成し、"
         f"令和７年度は{kenshu[2]}人まで伸びた"),
    ]
    hit = 0
    for child in doc.element.body.iterchildren():
        if child.tag != qn("w:tbl"):
            continue
        t = Table(child, doc)
        for row in t.rows:
            for cell in row.cells:
                for old, new in reps:
                    if cell.text.strip() == old.strip():
                        _write_cell(cell, new, size=9.5)
                        hit += 1
    if hit != len(reps):
        raise LookupError(f"第4章の実績の置換が{hit}件（{len(reps)}件のはず）")
    # 件数は上の assert が6件であることを保証している。
    # 修正履歴の生成器は本ファイルの changes.append を文字列として読むため、
    # ここに f文字列の差し込みを置くと履歴に未解決のまま現れる。
    changes.append("第4章：成果目標の実績【要更新】6件を、"
                   "村が公表した令和5〜7年度の進捗で埋めた"
                   "（令和8年5月25日 北塩原村障がい者自立支援協議会の資料）。"
                   "精神病床からの退院者数・就労定着支援・基幹相談支援センターは"
                   "令和7年度まで未達、一般就労移行と県研修への参加は達成")
    return m


def add_review2(doc):
    """第2回の外部レビュー（令和8年10月9日）への対応。

    レビューは他メンバーの素案を対象としているが、指摘のうち本文の記載に
    関わるものは当方の素案にも当てはまる。データの受領を待たずにできる
    ものをここで入れる（仮置き値の差し替えは村の回答後）。

    見込量表の直前に表や注記を差し込むと apply_mikomiryo が取り違えるため、
    本関数は main() で apply_mikomiryo の後に呼び、挿入位置も
    見込量表より後ろ（次の見出しの直前）に限る。
    """
    # (1) 第4章（１）施設入所者4人の地域移行0人を、個別の確認に基づくものにする
    anchor = find_para(doc, "本村の施設入所者数は、現行計画において")
    insert_after(anchor, [
        make_para(doc,
                  "地域移行者数を０人とする根拠を「重度であるため困難」に"
                  "とどめず、４人それぞれについて次の事項を確認したうえで"
                  "設定します。確認の結果は自立支援協議会に報告し、"
                  "本人又は家族が地域生活への移行を希望する場合には、"
                  "計画期間中であっても目標値を見直します。"),
        make_table(doc, [
            ["確認する事項", "確認の方法", "確認の時期"],
            ["本人の意向", "相談支援専門員によるモニタリング及び"
             "施設の地域移行等意向確認担当者による聴取",
             "年１回以上"],
            ["家族の意向", "相談支援専門員及び村による聴取", "年１回以上"],
            ["共同生活援助等の受入れの可能性",
             "会津北部地域生活支援拠点を通じた圏域の空き状況の照会", "年１回"],
            ["必要な医療の継続の可否",
             "入所先の施設及び協力医療機関への照会", "移行を検討する時"],
            ["夜間の支援体制",
             "移行先の共同生活援助の夜間支援体制等加算の状況の確認",
             "移行を検討する時"],
            ["地域生活の体験の機会",
             "地域生活支援拠点の体験の機会・場の機能の活用", "希望に応じて"],
        ], widths=[4600, 4000, 1600]),
        make_note(doc,
                  "【要確認：村】施設入所者４人について、上表の６項目のうち"
                  "現時点で確認できている事項を教えてください。"
                  "匿名の整理（年齢、障害支援区分、入所先の施設類型、"
                  "本人・家族の意向の確認状況）をいただけると、"
                  "目標値の根拠として本計画に記載できます。"
                  "あわせて、生活介護との同時支給決定の有無（介護保険の"
                  "適用除外の判定に用いる）も確認してください。"),
        make_empty(doc),
    ])

    # (2) 第4章（２）退院者1人の受け止め方を具体化する
    anchor = find_para(doc, "本村では、前期計画において、１年以上の長期入院者")
    insert_after(anchor, [
        make_para(doc,
                  "退院者１人の見込みは、退院後の生活の場と日中の過ごし方を"
                  "伴わなければ実現しません。本計画では、第５章６の"
                  "地域移行支援及び地域定着支援（令和10年度以降 各１人）、"
                  "第５章５の共同生活援助、第５章４の生活介護又は"
                  "自立訓練（生活訓練）、第５章６の計画相談支援を、"
                  "この１人の受け止めに充てる見込みとして整合させています。"
                  "住まいを共同生活援助とするか一般住宅とするかは本人の意向により、"
                  "一般住宅とする場合は自立生活援助と第５章８の"
                  "住まいの確保の取組みを用います。"),
        make_note(doc,
                  "【要確認：村】１年以上入院している方について、"
                  "退院後の住まい（共同生活援助・一般住宅・家族との同居）、"
                  "日中活動、医療の継続（通院先・訪問看護）、"
                  "相談支援の担当の見通しを、匿名で１人分整理してください。"
                  "見込量のどの行で受け止めるかを本計画に明示します。"),
        make_empty(doc),
    ])

    # (3) 第4章（３）一般就労中の一時的な利用・復職支援
    anchor = find_para(doc, "就労選択支援については、会津管内に事業所が設置されていない")
    insert_after(anchor, [
        make_para(doc,
                  "一般就労をしている方が、体調の悪化等により一時的に"
                  "就労系の障がい福祉サービスを利用し、又は休職を経て"
                  "復職する場合の支援についても、相談があった際に"
                  "対応できるようにします。本村の対象者は現時点でいませんが、"
                  "相談を受けた場合は、就労定着支援、ハローワーク"
                  "（会津若松公共職業安定所）、障害者就業・生活支援センター、"
                  "主治医及び事業主と連携して、就労の継続又は復職を支援します。"),
    ])

    # (4) 第4章（４）医療的ケア児等・重症心身障害児者を成人期まで広げる
    anchor = find_para(doc, "都道府県においては、医療的ケア児支援センターが")
    insert_after(anchor, [
        make_para(doc,
                  "支援の対象が医療的ケア児等（医療的ケア児及び医療的ケア者）"
                  "及び重症心身障害児者に広がったことを受け、"
                  "本村では次の３点を成人期まで続く支援として整理します。"
                  "第一に、児童期から成人期への引継ぎです。"
                  "18歳到達の前後で支援が途切れないよう、"
                  "相談支援専門員、医療機関、学校及び受入れ先の事業所による"
                  "協議を18歳到達の１年以上前から始めます。"
                  "第二に、家族の休息（レスパイト）です。"
                  "恒常的に医療的ケアを行う家族の負担は年単位で続くため、"
                  "短期入所（福祉型・医療型）及び日中一時支援を"
                  "家族の休息のための利用として位置づけます。"
                  "第三に、災害時の医療の継続です。"
                  "人工呼吸器等の電源の確保、医療材料の備蓄、"
                  "搬送先の確認を個別避難計画に盛り込みます。"),
        make_note(doc,
                  "【要確認：村】18歳以上で恒常的に医療的ケアを受けている方"
                  "（医療的ケア者）と、重症心身障害の状態にある成人の方の"
                  "人数及び利用しているサービスを確認してください。"
                  "いない場合も「現時点で該当なし」として記録します。"
                  "第５章４・５の重度障がい者の内数に計上します。"),
        make_empty(doc),
    ])

    # (5) 第5章4の末尾（居住系の直前）に重度障がい者の内数と医療型短期入所の注記
    anchor = find_para(doc, "５　居住系サービス", style="Heading 2")
    insert_before(anchor, [
        make_para(doc, "■　重度障がい者の内数", style="Heading 3"),
        make_para(doc,
                  "基本指針 別表第一 三は、生活介護の利用者数のうち、"
                  "強度行動障害の状態にある方、高次脳機能障害を有する方、"
                  "医療的ケアを必要とする方等の重度障がい者について、"
                  "個別に利用者数の見込みを設定するよう努めることとしています。"
                  "本村の対象者は少数であるため、個人が特定されない範囲で"
                  "次のとおり内数を示します。"),
        make_table(doc, [
            ["区分", "現在の人数", "令和９年度", "令和10年度", "令和11年度",
             "主に必要となるサービス"],
            ["強度行動障害の状態にある方", "【要確認】", "―", "―", "―",
             "行動援護、生活介護、短期入所、共同生活援助"],
            ["高次脳機能障害を有する方", "【要確認】", "―", "―", "―",
             "居宅介護、計画相談支援、就労継続支援、自立訓練"],
            ["医療的ケア児等（児・者）", "児１人", "―", "―", "―",
             "児童発達支援、放課後等デイサービス、短期入所、生活介護"],
            ["重症心身障害の状態にある児者", "【要確認】", "―", "―", "―",
             "生活介護、児童発達支援、放課後等デイサービス、短期入所"],
        ], widths=[3400, 1500, 1300, 1300, 1300, 4300]),
        make_note(doc,
                  "【要確認：村】上表の人数を確認してください。"
                  "強度行動障害は障害支援区分の認定調査の行動関連項目の"
                  "合計点（10点以上）、高次脳機能障害は診断の有無、"
                  "重症心身障害は大島分類により判定します。"
                  "村内に該当する方がいない区分は０と記載し、"
                  "「把握していない」と「該当なし」を区別します。"
                  "令和９〜11年度の内数は、現在の人数に、"
                  "年齢到達による移行（第５章２）と"
                  "学校卒業に伴う移行を加えて設定します。"),
        make_empty(doc),
        make_para(doc,
                  "短期入所（医療型）の見込量を０としているのは、"
                  "現時点で利用の希望を把握していないためです。"
                  "本村には医療的ケア児が１人おり、家族の休息や"
                  "緊急時の受入れのために医療型短期入所が必要になる可能性が"
                  "あることから、個別の意向を確認したうえで最終の見込量を"
                  "確定させます。利用の希望があった場合は、"
                  "圏域及び会津若松市等の医療型短期入所を実施する"
                  "医療機関との調整を行います。"),
        make_empty(doc),
    ])

    # (6) 第5章8の末尾（地域生活支援事業の直前）に4項目
    anchor = find_para(doc, "９　地域生活支援事業の実施目標", style="Heading 2")
    insert_before(anchor, [
        make_para(doc, "■　事業所の受入余力の把握", style="Heading 3"),
        make_para(doc,
                  "圏域に事業所があることは、本村の住民がそのサービスを"
                  "利用できることと同じではありません。"
                  "本村の住民が利用している村外の事業所に対し、"
                  "次の事項を照会し、確保可能量の判断に用います。"
                  "照会は自立支援協議会及び会津北部地域生活支援拠点を通じて"
                  "行い、結果は年１回更新します。"),
        make_table(doc, [
            ["照会する事項", "確保可能量との関係"],
            ["定員、現在の利用者数、空き、待機の有無",
             "新規に受け入れられる人数の上限"],
            ["送迎の実施の有無と送迎の範囲",
             "本村から通えるかどうか。片道の距離と所要時間"],
            ["冬季（積雪期）の送迎及び通所の可否",
             "冬季に利用が途切れないかどうか。本村では最も重い制約"],
            ["重度障がい者（強度行動障害・高次脳機能障害）の受入れの可否",
             "重度障がい者の内数を受け止められるかどうか"],
            ["医療的ケアへの対応の可否（看護職員の配置）",
             "医療的ケア児等の受入れの可否"],
            ["職員の欠員の状況と採用の見通し",
             "定員に空きがあっても受け入れられない場合がある"],
            ["令和９〜11年度の定員の増減又は休廃止の意向",
             "計画期間中に確保可能量が減る見込みの有無"],
        ], widths=[7600, 7600]),
        make_note(doc,
                  "【要確認：村】本村の住民が利用している村外の事業所の"
                  "一覧（サービス種別・事業所名・所在地）をいただければ、"
                  "上表の照会文を当方で作成します。"
                  "個別の事業所名を計画本文に載せるかどうかは村の判断に委ねます。"),
        make_empty(doc),
        make_para(doc, "■　住まいの確保", style="Heading 3"),
        make_para(doc,
                  "施設入所者及び精神科病院の長期入院者の地域生活への移行は、"
                  "住まいが確保できなければ進みません。"
                  "共同生活援助及び自立生活援助に加えて、"
                  "住宅セーフティネット制度との連携により一般住宅での"
                  "生活の選択肢を広げます。具体的には、"
                  "村の住宅担当部局との情報共有、"
                  "県が指定する居住支援法人及び居住支援協議会との連携、"
                  "民間賃貸住宅の家主の理解促進、"
                  "保証人を確保できない場合の家賃債務保証の仕組みの案内を行います。"
                  "住まいの相談は相談支援事業所が入口となるため、"
                  "第５章６の計画相談支援及び基幹相談支援センターの機能と"
                  "一体で進めます。"),
        make_empty(doc),
        make_para(doc, "■　供給が不足する場合の県への意見申出", style="Heading 3"),
        make_para(doc,
                  "障がい福祉サービス事業者の指定は県が行い、本村は"
                  "指定の権限を有しません。本計画の見込量に対して"
                  "圏域の供給が不足する場合、又は特定のサービスに偏った"
                  "指定が行われる場合には、県が行う指定に対して"
                  "市町村が意見を申し出る仕組み（意見申出制度）を用います。"
                  "あわせて、圏域の供給の不足と待機の状況を"
                  "会津北部圏域の町村及び県（会津保健福祉事務所）と共有し、"
                  "圏域単位での基盤整備（第５章８の圏域の整備計画）に結び付けます。"),
        make_empty(doc),
        make_para(doc, "■　中山間・人口減少地域の制度の活用", style="Heading 3"),
        make_para(doc,
                  "令和８年６月に公布された社会福祉法等の一部を改正する法律により、"
                  "中山間地域・人口減少地域を対象として、"
                  "地域の実情に応じた基準を設けることができる"
                  "サービスの類型（特定地域サービス）が設けられました。"
                  "障がい福祉及び障がい児通所支援においても同様の仕組みが"
                  "設けられるとされています。本村は全域が過疎地域であり、"
                  "県条例の中山間地域にも該当するため、"
                  "対象地域の基準及び運用が示された後に、"
                  "本村の供給の状況を踏まえて活用の可能性を検討します。"),
        make_note(doc,
                  "【要確認：県】特定地域サービス等の対象地域の基準、"
                  "県が定める区域の指定の予定、障がい福祉分野での施行期日を"
                  "確認してください。あわせて、法律番号及び施行期日の原典"
                  "（厚生労働省の公表資料）の提供を依頼します"
                  "（当方は令和８年６月の公布までを確認しています）。"),
        make_empty(doc),
    ])

    # (7) 第5章11の末尾（費用・財源の直前）に災害時の継続と虐待の予防
    anchor = find_para(doc, "12　障がい福祉サービス等に係る費用の推移と財源構成",
                       style="Heading 2")
    insert_before(anchor, [
        make_para(doc, "■　災害時にサービスを止めないための備え", style="Heading 3"),
        make_para(doc,
                  "本村は冬季の積雪と火山・地震の災害リスクを併せ持ち、"
                  "多くのサービスを村外の事業所に依存しています。"
                  "避難そのものへの備え（個別避難計画。第３章３）とは別に、"
                  "災害時にサービスの提供を止めないための備えを次のとおり進めます。"),
        make_table(doc, [
            ["備える事項", "本村の取組み"],
            ["医療機器の電源の確保",
             "人工呼吸器等を使用する方について、非常用電源の確保と"
             "停電時の連絡手順を個別避難計画に盛り込む"],
            ["事業所の業務継続計画（ＢＣＰ）",
             "村内及び圏域の事業所の業務継続計画の策定状況を確認し、"
             "県の研修の情報を提供する"],
            ["冬季の通行不能への備え",
             "冬季の通行規制等により通常利用しているサービスの利用が"
             "困難となる場合に備え、本人の支援の必要性、支給決定の状況"
             "及び事業所の受入れの可能性を踏まえ、代替となる支援の方法を"
             "相談支援事業所及びサービス事業所とあらかじめ検討する。"
             "通行止めの際は訪問の車両も居宅に到達できない場合があるため、"
             "振替え先をあらかじめ一つに決めない"],
            ["村外の通所先が停止した場合の代替",
             "会津北部地域生活支援拠点等の関係機関と連携し、"
             "圏域内で利用できる代替の支援を調整する。"
             "拠点が空床の情報の保有や代替の受入れの調整を"
             "実際に担えるかは、運用の状況を確かめたうえで判断する"],
            ["安否確認と情報の共有",
             "相談支援事業所及び民生児童委員と連携し、"
             "サービス利用者の安否と支援の必要性を確認する"],
        ], widths=[4200, 11000]),
        make_empty(doc),
        make_para(doc, "■　虐待の予防から再発の防止まで", style="Heading 3"),
        make_para(doc,
                  "障がい者虐待への対応は、通報を受けてからの対応だけでなく、"
                  "虐待に至る前の家族の負担の把握が要になります。"
                  "本村では、家族の介護負担の把握から再発の防止までを"
                  "一続きの流れとして整理します。"),
        make_table(doc, [
            ["段階", "本村の取組み", "用いるサービス等"],
            ["① 予防（家族の負担の把握）",
             "相談支援専門員のモニタリング及び民生児童委員の見守りにより、"
             "介護者の健康状態と負担を把握する",
             "計画相談支援、相談支援事業"],
            ["② 負担の軽減",
             "家族の休息のための利用を勧め、"
             "緊急時に受け止められる体制を保つ",
             "短期入所、日中一時支援、居宅介護、"
             "会津北部地域生活支援拠点の緊急時の受入れ"],
            ["③ 養護者への支援",
             "養護者自身が支援を必要とする場合は、"
             "高齢者福祉・生活困窮者自立支援・保健の窓口につなぐ",
             "地域包括支援センター、保健師、生活困窮者自立相談支援"],
            ["④ 通報の受理と初動",
             "村が窓口となり、通報・届出を受理して速やかに"
             "本人の安全を確認する", "―"],
            ["⑤ 事実の確認と措置",
             "県及び相談支援事業所と連携して事実確認を行い、"
             "必要な場合は分離の措置（短期入所等）を講じる",
             "短期入所、施設入所支援"],
            ["⑥ 検証と再発の防止",
             "重篤な事例は自立支援協議会（専門部会）で検証し、"
             "再発の防止策を関係機関で共有する", "自立支援協議会"],
        ], widths=[3000, 7000, 5200]),
        make_empty(doc),
    ])

    # (8) 第5章13 意思決定支援の3段階と、経営基盤を供給制約として見ること
    anchor = find_para(doc, "本村では、県の普及啓発及び研修の情報を村内及び圏域の事業所へ")
    insert_after(anchor, [
        make_para(doc,
                  "意思決定支援は、本人の意思を「形づくる」「表す」「実現する」"
                  "の各段階を通じて支えるものです。"
                  "意思形成の段階では、選択肢を本人に分かる形で示し、"
                  "体験の機会を用意します。"
                  "意思表明の段階では、時間をかけて聴き取り、"
                  "表明された意思が変わり得ることを前提に確認を重ねます。"
                  "意思実現の段階では、表明された意思が実際のサービス利用に"
                  "結び付くよう、関係機関が役割を分担します。"
                  "本村では、支給決定、サービス等利用計画の作成、"
                  "施設入所者及び長期入院者の地域移行、"
                  "成年後見制度の利用のいずれの場面においても、"
                  "この３つの段階を通じて本人の意思及び選好を尊重することを基本とします。"),
        make_note(doc,
                  "【要確認：県】意思決定支援ガイドラインの改定の状況"
                  "（令和８年７月10日の社会保障審議会障害者部会に"
                  "第２版の案が示されています）と、"
                  "県が実施する研修の予定を確認してください。"
                  "確定後、上記の記載を改定後の用語に揃えます。"),
        make_empty(doc),
    ])

    anchor = find_para(doc, "14　関係機関との連携", style="Heading 2")
    insert_before(anchor, [
        make_para(doc, "■　経営基盤を供給制約として見る", style="Heading 3"),
        make_para(doc,
                  "基本指針が人材確保と並べて経営基盤の確立を掲げたのは、"
                  "事業所が存続しなければ見込量を確保できないためです。"
                  "本村の住民が利用する事業所は小規模なものが多く、"
                  "村外からの送迎の負担も加わります。"
                  "次の事項を供給の制約として把握し、"
                  "第５章８の確保可能量の判断に反映させます。"),
        make_table(doc, [
            ["把握する事項", "見込量への影響"],
            ["職員の欠員の状況と採用の難しさ",
             "定員に空きがあっても受け入れられない"],
            ["職員の離職の状況",
             "支援の質と受入れの継続性に影響する"],
            ["事業の休止・廃止の意向",
             "計画期間中に確保可能量が失われる"],
            ["小規模な事業所の採算（利用者数の変動の影響）",
             "本村のように利用者が少数の地域では、"
             "１人の利用の中断が事業の継続に響く"],
            ["冬季の送迎に要する費用と人員",
             "冬季に送迎の範囲が縮まると通所できなくなる"],
            ["福祉・介護職員等処遇改善加算の取得の状況",
             "職員の確保・定着の度合いを測る目安となる"],
        ], widths=[7000, 8200]),
        make_note(doc,
                  "【要確認：村】村内３事業所及び本村の住民が利用している"
                  "村外の主な事業所について、上表の事項を"
                  "自立支援協議会の場で確認できないか検討してください。"
                  "事業所名を伏せた集計でも、確保可能量の判断には足ります。"),
        make_empty(doc),
    ])

    # (9) 第6章 成年後見制度の見直し
    anchor = find_para(doc, "第7章　他計画との連携", style="Heading 1")
    insert_before(anchor, [
        make_para(doc, "３　制度の見直しへの対応", style="Heading 2"),
        make_para(doc,
                  "成年後見制度については、令和８年６月に民法等の一部を"
                  "改正する法律が公布され、法定後見の見直しが行われました。"
                  "後見及び保佐を廃止して補助に一元化し、"
                  "家庭裁判所が本人に必要な範囲で支援の内容を定めること、"
                  "制度の利用を終身を前提とせず、"
                  "必要がなくなったと認められるときは終了できることとすること、"
                  "補助人が職務を行うにあたって本人の意向を把握することを"
                  "明確にすることなどが内容とされています。"
                  "施行は公布から一定の期間の後に政令で定める日とされており、"
                  "本計画期間中又はその後に施行される可能性があります。"),
        make_para(doc,
                  "本村では、施行の時期と内容が明らかになった段階で、"
                  "中核機関（会津権利擁護・成年後見センター）及び"
                  "家庭裁判所と連携して、村長申立ての運用、"
                  "成年後見制度利用支援事業の助成の対象、"
                  "住民への周知の内容を見直します。"
                  "制度が本人の意思を尊重する方向に改められることは、"
                  "第５章13の意思決定支援の考え方と同じ方向にあり、"
                  "両者を一体で進めます。"),
        make_note(doc,
                  "【要確認：村・県】民法等の一部を改正する法律"
                  "（成年後見等関係）の法律番号、公布日及び施行期日を"
                  "確認してください。当方は厚生労働省及び法務省の"
                  "公表資料により令和８年６月の公布までを確認しましたが、"
                  "原典の取得ができていません。"
                  "計画の確定前に、中核機関を通じて確認します。"),
        make_empty(doc),
    ])

    changes.append("第4章（１）：地域移行者数の目標値0人の根拠を、"
                   "本人・家族の意向ほか6項目の確認に基づくものに改め、確認表を新設")
    changes.append("第4章（２）：退院者1人の受け止め方（住まい・日中活動・相談支援）を"
                   "見込量の行と対応させて明示")
    changes.append("第4章（３）：一般就労中の一時的な就労系サービスの利用と復職支援を追加")
    changes.append("第4章（４）：令和8年8月19日の基本指針の改正を踏まえ、"
                   "医療的ケア児等・重症心身障害児者について成人期への引継ぎ・"
                   "家族の休息・災害時の医療の継続の3点を追加")
    changes.append("第5章4：基本指針 別表第一 三が求める重度障がい者の内数"
                   "（強度行動障害・高次脳機能障害・医療的ケア児等・"
                   "重症心身障害児者の4区分）の表を新設し、"
                   "医療型短期入所を0とする根拠を明示")
    changes.append("第5章8：確保方策に4節を追加（事業所の受入余力の把握7項目、"
                   "住まいの確保、供給が不足する場合の県への意見申出、"
                   "中山間・人口減少地域の制度の活用）")
    changes.append("第5章11：災害時にサービスを止めないための備えと、"
                   "虐待の予防から再発の防止までの6段階を新設")
    changes.append("第5章13：意思決定支援を意思形成・意思表明・意思実現の3段階で整理し、"
                   "経営基盤を供給制約として把握する6項目を新設")
    changes.append("第6章3：成年後見制度の見直し（令和8年6月公布の民法等改正。"
                   "後見・保佐を補助に一元化）への対応を新設")


def verify_output(doc):
    """保存前の自己点検。

    注記ボックスは1x1の表であるため、見込量表の直前に差し込むと
    apply_mikomiryo が注記を見込量表と取り違え、見込量が消えたまま
    警告なく保存されてしまう（令和8年10月8日に実際に起きた）。
    表の中身まで見る点検をここに置き、同じ壊れ方を二度させない。
    """
    ng = []

    # 1 見込量表が5つとも新しい表頭で、データ行を持つこと
    for heading, _kubuns, _label in MIKOMI_TABLES:
        head = find_para(doc, heading, style="Heading 2")
        t = Table(find_block_after(doc, head, "tbl"), doc)
        hdr = [c.text.strip().replace("\n", "") for c in t.rows[0].cells]
        if len(t.columns) != 8 or hdr[0] != "サービス種別" or hdr[2] != "令和７年度請求件数":
            ng.append(f"{heading}：見込量表の表頭が差し替わっていない（{hdr[:3]}）")
        elif len(t.rows) < 2:
            ng.append(f"{heading}：見込量表にデータ行がない（見込量が消えている）")

    # 2 「R8」のような略記の年度表記が残っていないこと（本文は令和表記に揃える）
    for child in doc.element.body.iterchildren():
        if child.tag != qn("w:tbl"):
            continue
        t = Table(child, doc)
        if len(t.columns) < 2:
            continue                     # 1x1 は注記ボックス
        hdr = " ".join(c.text.strip().replace("\n", "") for c in t.rows[0].cells)
        if re.search(r"R\d+\s*(見込量|実績|年度)", hdr):
            ng.append(f"表頭に略記の年度表記が残っている（{hdr[:60]}）")

    # 3 廃止区分が表の行名として残っていないこと（注記での言及は可）
    for child in doc.element.body.iterchildren():
        if child.tag != qn("w:tbl"):
            continue
        t = Table(child, doc)
        if len(t.columns) < 2:
            continue
        for row in t.rows:
            if row.cells[0].text.strip() == "医療型児童発達支援":
                ng.append("表の行名に廃止区分「医療型児童発達支援」が残っている")

    # 4 第5章7のサービスの内容が①から連番であること
    #   見出し「７　障がい児支援」から次の表までの段落だけを見る。
    maru = "①②③④⑤⑥⑦⑧⑨"
    head = find_para(doc, "７　障がい児支援", style="Heading 2")
    found = []
    for sib in head.itersiblings():
        if sib.tag == qn("w:tbl"):
            break
        if sib.tag == qn("w:p"):
            t = Paragraph(sib, doc).text.strip()
            if t and t[0] in maru:
                found.append(t[0])
    if found != list(maru[:len(found)]):
        ng.append(f"第5章7のサービスの内容の番号が連番でない: {''.join(found)}")
    if len(found) != 6:
        ng.append(f"第5章7のサービスの内容が6件でない: {len(found)}件")

    # 5 福島県の計画との整合の3節があること
    for h in ("■　福島県の計画との整合", "■　県が定める区域と本計画でいう圏域",
              "■　県の成果目標との関係"):
        try:
            find_para(doc, h, style="Heading 3")
        except LookupError:
            ng.append(f"第1章2に「{h}」がない")

    # 5b 県計画から引いた圏域の構成市町村が原典どおりであること
    ken = KEN_PDF_TEXT
    for muni in ("会津若松市", "喜多方市", "北塩原村", "西会津町", "磐梯町",
                 "猪苗代町", "会津坂下町", "湯川村", "柳津町", "三島町",
                 "金山町", "昭和村", "会津美里町"):
        if muni not in ken:
            ng.append(f"県計画の会津圏域に{muni}が見つからない")
    for q in ("この計画の期間は、令和6年度から令和8年度までの3年間とします",
              "引き続き7つの障がい保健福祉圏域とします",
              "福島県障がい者計画の実施計画として位置付けられています",
              "全県で広域的に行うこととします",
              # 会津圏域計画（第9 圏域計画）から引いたもの
              "会津若松市、喜多方市、会津北部、会津西部の4つの拠点が整備されています",
              "基幹相談支援センターが設置されていない市町村に対して設置促進",
              "相談支援アドバイザー",
              # 第5次福島県障がい者計画から引いたもの
              "本計画の期間は、「福島県総合計画」及び"
              "「福島県保健医療福祉復興ビジョン」との整合を図るため、"
              "目標年度を合わせ、令和4年度から令和12年度までの9年間とします",
              "障害者基本法第11条第2項において規定される都道府県障害者計画",
              "障害者文化芸術活動推進法第8条", "読書バリアフリー法第8条",
              "障がいのある方の人権、人格が尊重され、"
              "等しく社会の一員として生活できる社会の実現",
              "障がいのある人もない人も共に暮らしやすい福島県づくり条例",
              "福島県手話言語条例",
              "重点施策⑦：障がいのある方のアクセシビリティの向上"):
        if _norm_ken(q) not in ken:
            ng.append(f"県計画の原典に見つからない引用: {q}")

    # 5d 県障がい者計画の9つの重点施策が、対応表に残らず現れていること
    taikei = _norm_ken("".join(r[1] for r in KEN_TAIKEI[1:]))
    for juten in ("生活支援", "保健・医療・福祉",
                  "ライフステージに応じた障がいのある子どもへの支援",
                  "文化芸術・スポーツ活動の振興、社会参加の促進",
                  "雇用・就業、経済的自立の支援", "生活環境",
                  "障がいのある方のアクセシビリティの向上", "安全・安心",
                  "差別の解消及び権利擁護の推進"):
        if _norm_ken(juten) not in taikei:
            ng.append(f"施策体系の対応表に県の重点施策が落ちている: {juten}")
        if _norm_ken(juten) not in ken:
            ng.append(f"県障がい者計画の原典にない重点施策: {juten}")
    if len(KEN_TAIKEI) - 1 != 8:
        ng.append(f"対応表の行数が本計画の基本施策7件＋未対応1件と合わない: "
                  f"{len(KEN_TAIKEI) - 1}")

    # 5c 県計画から転記した数値が原典に実在すること
    #    空白と全角数字を落としたうえで、数値を含む語のまま照合する。
    for num in (
            # 県全体（概要）
            "地域生活支援拠点設置市町村数・箇所数59市町村39カ所",
            "基幹相談支援センターの設置市町村数（複数市町村による共同設置を含む）"
            "－44－59市町村",
            "一般就労移行者数:218人うち就労移行支援事業:147人",
            # 会津圏域計画 6 令和8年度の数値目標
            "地域生活支援拠点設置市町村数・箇所数13市町村5か所",
            "コーディネーターの配置人数7人",
            "基幹相談支援センターの設置市町村数（複数市町村による共同設置を含む）13市町村",
            # 会津圏域計画（障がい児支援）3 支援サービス等の整備状況
            "児童発達支援センター1か所（会津若松市1",
            "保育所等訪問支援事業所6か所（会津若松市6",
            "福祉型障害児入所施設1か所（猪苗代町1",
            # 会津圏域計画 8 新たに必要となる事業所数
            "共同生活援助（GH）箇所34353536",
    ):
        if _norm_ken(num) not in ken:
            ng.append(f"県計画の原典に見つからない数値: {num}")

    # 6 注記が実在しない列名を指していないこと
    for child in doc.element.body.iterchildren():
        if child.tag != qn("w:tbl"):
            continue
        t = Table(child, doc)
        if len(t.columns) != 1:
            continue
        if re.search(r"R\d+(～R\d+|\s*(見込量|実績|年度))", t.cell(0, 0).text):
            ng.append(f"注記が略記の年度表記を使っている（{t.cell(0, 0).text[:50]}）")

    if ng:
        raise SystemExit("自己点検 不合格:\n  - " + "\n  - ".join(ng))
    print(f"自己点検: 合格　見込量表5件にデータ行あり／略記の年度表記0件／"
          f"廃止区分の行0件／サービスの内容の番号 {''.join(found)}")


def main():
    if not os.path.exists(SRC_FILE):
        raise SystemExit(f"原本が見つかりません: {SRC_FILE}")
    os.makedirs(OUT_DIR, exist_ok=True)

    verify_service_names()
    doc = docx.Document(SRC_FILE)
    revise_population(doc)
    fix_prev_survey(doc)
    add_tegata_projection(doc)
    add_survey_design(doc)
    rebuild_chapter3(doc)
    fix_facility_baseline(doc)
    add_kodomo_katei_center(doc)
    add_ken_keikaku(doc)            # 第1章2 福島県の計画との整合
    add_ken_shogaisha_keikaku(doc)  # 第1章2 県障がい者計画の基本目標との対応
    drop_abolished_child_service(doc)   # 第5章7 廃止区分の削除
    add_funding_section(doc)
    add_estimation_method(doc)
    add_estimation_basis(doc)
    add_kubun_verification(doc)
    add_kakuho_hosaku(doc)
    add_chiiki_kangaekata(doc)
    add_katsudou_shihyou(doc)
    apply_kokuji_verification(doc)
    add_misc_notes(doc)
    apply_village_data(doc)
    fix_shokan_ka(doc)
    add_manual_comparison(doc)
    add_pdca_detail(doc)
    add_service_taikei(doc)
    add_hyoki_note(doc)
    # レビュー優先度「高」の4件（R-1〜R-4）
    add_kiban_seibi_ryo(doc)     # R-2 第4章(2) 基盤整備量
    add_iryo_care(doc)           # R-3 第4章(4)・第5章2 医療的ケア児等
    add_jinzai_kakuho(doc)       # R-1 第5章13 人材確保・生産性向上・経営基盤
    add_kankei_kikan(doc)        # R-4 第5章14 関係機関との連携
    add_ken_kenikai(doc)         # 県計画の会津圏域計画を第4章（4）（6）・第5章8へ
    add_yougo_kaisetsu(doc)      # 用語解説は追加語を含めるため R-3 の後に置く
    apply_mikomiryo(doc)         # 第5章3〜7 見込量を第1次概算に差し替え
    apply_anq_result(doc)        # 第2章8 アンケートを実施結果へ
    apply_kpi_result(doc)        # 第3章5 目標値表に調査結果と比較可能性
    # 第2回レビュー（令和8年10月9日）の対応。表・注記を差し込むため、
    # 見込量表を確定させた apply_mikomiryo の後に置く
    add_review2(doc)
    fix_section_refs(doc)
    fix_title(doc)
    apply_mura_jisseki(doc)
    load_ken_pdf()
    verify_output(doc)
    doc.save(OUT_FILE)

    print(f"作成: {OUT_FILE}")
    print("反映した修正:")
    for c in changes:
        print(f"  - {c}")


if __name__ == "__main__":
    main()
